/**
 * The single, stable gRPC service contract.
 * Adding or removing a HAL module never modifies this file.
 */
export interface HalService {
  /** Run tests once (TestBase::SINGLE_SHOT). */
  RunSingleShot(request: SingleShotRequest): Promise<ResultEnvelope>;
  /** Run tests repeatedly for a fixed duration (TestBase::LONG_TERM). */
  StartLongTerm(request: LongTermRequest): Observable<ResultEnvelope>;
  /** Run tests indefinitely, sampling monitor items each cycle (TestBase::MONITORING). */
  StartMonitoring(request: MonitoringRequest): Observable<ResultEnvelope>;
  /** Poll tests continuously and stream results when the condition fires (TestBase::EVENT_BASED). */
  StartEventBased(request: EventBasedRequest): Observable<ResultEnvelope>;
  /** Stop any active background session for a module. */
  Stop(request: StopRequest): Promise<StopResponse>;
  /** Pause any active background session for a module. */
  Pause(request: PauseRequest): Promise<PauseResponse>;
  /** Resume any paused background session for a module. */
  Resume(request: ResumeRequest): Promise<ResumeResponse>;
  /** Return the server-side module registry. */
  ListModules(request: ListModulesRequest): Promise<ListModulesResponse>;
}

export const HalServiceServiceName = "hal.HalService";
export class HalServiceClientImpl implements HalService {
  private readonly rpc: Rpc;
  private readonly service: string;
  constructor(rpc: Rpc, opts?: { service?: string }) {
    this.service = opts?.service || HalServiceServiceName;
    this.rpc = rpc;
    this.RunSingleShot = this.RunSingleShot.bind(this);
    this.StartLongTerm = this.StartLongTerm.bind(this);
    this.StartMonitoring = this.StartMonitoring.bind(this);
    this.StartEventBased = this.StartEventBased.bind(this);
    this.Stop = this.Stop.bind(this);
    this.Pause = this.Pause.bind(this);
    this.Resume = this.Resume.bind(this);
    this.ListModules = this.ListModules.bind(this);
  }
  RunSingleShot(request: SingleShotRequest): Promise<ResultEnvelope> {
    const data = SingleShotRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "RunSingleShot", data);
    return promise.then((data) => ResultEnvelope.decode(new BinaryReader(data)));
  }

  StartLongTerm(request: LongTermRequest): Observable<ResultEnvelope> {
    const data = LongTermRequest.encode(request).finish();
    const result = this.rpc.serverStreamingRequest(this.service, "StartLongTerm", data);
    return result.pipe(map((data) => ResultEnvelope.decode(new BinaryReader(data))));
  }

  StartMonitoring(request: MonitoringRequest): Observable<ResultEnvelope> {
    const data = MonitoringRequest.encode(request).finish();
    const result = this.rpc.serverStreamingRequest(this.service, "StartMonitoring", data);
    return result.pipe(map((data) => ResultEnvelope.decode(new BinaryReader(data))));
  }

  StartEventBased(request: EventBasedRequest): Observable<ResultEnvelope> {
    const data = EventBasedRequest.encode(request).finish();
    const result = this.rpc.serverStreamingRequest(this.service, "StartEventBased", data);
    return result.pipe(map((data) => ResultEnvelope.decode(new BinaryReader(data))));
  }

  Stop(request: StopRequest): Promise<StopResponse> {
    const data = StopRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "Stop", data);
    return promise.then((data) => StopResponse.decode(new BinaryReader(data)));
  }

  Pause(request: PauseRequest): Promise<PauseResponse> {
    const data = PauseRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "Pause", data);
    return promise.then((data) => PauseResponse.decode(new BinaryReader(data)));
  }

  Resume(request: ResumeRequest): Promise<ResumeResponse> {
    const data = ResumeRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "Resume", data);
    return promise.then((data) => ResumeResponse.decode(new BinaryReader(data)));
  }

  ListModules(request: ListModulesRequest): Promise<ListModulesResponse> {
    const data = ListModulesRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "ListModules", data);
    return promise.then((data) => ListModulesResponse.decode(new BinaryReader(data)));
  }
}

interface Rpc {
  request(service: string, method: string, data: Uint8Array): Promise<Uint8Array>;
  clientStreamingRequest(service: string, method: string, data: Observable<Uint8Array>): Promise<Uint8Array>;
  serverStreamingRequest(service: string, method: string, data: Uint8Array): Observable<Uint8Array>;
  bidirectionalStreamingRequest(service: string, method: string, data: Observable<Uint8Array>): Observable<Uint8Array>;
}

type Builtin = Date | Function | Uint8Array | string | number | boolean | undefined;

type DeepPartial<T> = T extends Builtin ? T
  : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

type KeysOfUnion<T> = T extends T ? keyof T : never;
type Exact<P, I extends P> = P extends Builtin ? P
  : P & { [K in keyof P]: Exact<P[K], I[K]> } & { [K in Exclude<keyof I, KeysOfUnion<P>>]: never };

function isSet(value: any): boolean {
  return value !== null && value !== undefined;
}

interface MessageFns<T> {
  encode(message: T, writer?: BinaryWriter): BinaryWriter;
  decode(input: BinaryReader | Uint8Array, length?: number): T;
  fromJSON(object: any): T;
  toJSON(message: T): unknown;
  create<I extends Exact<DeepPartial<T>, I>>(base?: I): T;
  fromPartial<I extends Exact<DeepPartial<T>, I>>(object: I): T;
}
